const PRIVATE_IN_PREFIX: &str = "__private_in__:";
const RAW_SURROGATE_MARKER_BASE: u32 = 0xF0000;
const RAW_SURROGATE_MARKER_UTF8_LEAD: u8 = 0xF3;

fn cooked_text_may_contain_raw_surrogate_marker(s: &str) -> bool {
    s.as_bytes().contains(&RAW_SURROGATE_MARKER_UTF8_LEAD)
}

fn marker_string_to_wtf_units(s: &str) -> Option<Vec<u16>> {
    let mut units = Vec::new();
    let mut saw_marker = false;
    for ch in s.chars() {
        let cp = ch as u32;
        if let Some(offset) = cp.checked_sub(RAW_SURROGATE_MARKER_BASE) {
            if offset <= 0x7ff {
                units.push(0xD800 + offset as u16);
                saw_marker = true;
                continue;
            }
        }
        let mut buf = [0u16; 2];
        units.extend_from_slice(ch.encode_utf16(&mut buf));
    }
    saw_marker.then_some(units)
}

fn string_constant_for_cooked_text(s: &str) -> Constant {
    if !cooked_text_may_contain_raw_surrogate_marker(s) {
        return Constant::String(s.to_string());
    }
    marker_string_to_wtf_units(s)
        .map(Constant::WtfString)
        .unwrap_or_else(|| Constant::String(s.to_string()))
}

fn number_property_key(n: f64) -> String {
    if n.is_nan() {
        return "NaN".to_string();
    }
    if n == f64::INFINITY {
        return "Infinity".to_string();
    }
    if n == f64::NEG_INFINITY {
        return "-Infinity".to_string();
    }
    if n == 0.0 {
        return "0".to_string();
    }
    if n.fract() == 0.0 && n.abs() < 1e21 {
        if n.abs() < (1u64 << 53) as f64 {
            return format!("{}", n as i64);
        }
        return format!("{:.0}", n);
    }
    if n.abs() < 1e-6 || n.abs() >= 1e21 {
        let s = format!("{:e}", n);
        let mut out = String::new();
        let bytes = s.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let c = bytes[i] as char;
            out.push(c);
            if c == 'e'
                && i + 1 < bytes.len()
                && bytes[i + 1] as char != '-'
                && bytes[i + 1] as char != '+'
            {
                out.push('+');
            }
            i += 1;
        }
        return out;
    }
    format!("{}", n)
}

fn labelled_function_decl(
    stmt: &Stmt,
) -> Option<(&BindingIdentifier, bool, bool, &[Parameter], &[Stmt], Span)> {
    match stmt {
        Stmt::FunctionDecl {
            name: Some(name),
            is_async,
            is_generator,
            params,
            body,
            span,
            ..
        } => Some((name, *is_async, *is_generator, params, body, *span)),
        Stmt::Labelled { body, .. } => labelled_function_decl(body),
        _ => None,
    }
}

fn add_profile_bucket(bucket: &mut (u64, u64), elapsed_ns: u64) {
    bucket.0 = bucket.0.saturating_add(1);
    bucket.1 = bucket.1.saturating_add(elapsed_ns);
}

fn babel_default_variable_kind_family(kind: VariableKind) -> &'static str {
    match kind {
        VariableKind::Var => "var",
        VariableKind::Let => "let",
        VariableKind::Const => "const",
        VariableKind::Using => "using",
        VariableKind::AwaitUsing => "await_using",
    }
}

fn babel_default_binding_pattern_family(pattern: &BindingPattern) -> &'static str {
    match pattern {
        BindingPattern::Identifier(_) => "identifier",
        BindingPattern::Array(_) => "array",
        BindingPattern::Object(_) => "object",
    }
}

fn babel_default_init_expr_family(init: Option<&Expr>) -> &'static str {
    match init {
        None => "none",
        Some(
            Expr::NullLiteral { .. }
            | Expr::BoolLiteral { .. }
            | Expr::NumberLiteral { .. }
            | Expr::BigIntLiteral { .. }
            | Expr::StringLiteral { .. }
            | Expr::WtfStringLiteral { .. }
            | Expr::TemplateLiteral { .. }
            | Expr::TemplateObject { .. }
            | Expr::RegExp { .. },
        ) => "literal",
        Some(Expr::Identifier { .. } | Expr::This { .. } | Expr::Super { .. }) => "identifier",
        Some(Expr::Member { .. } | Expr::MetaProperty { .. }) => "member",
        Some(Expr::Call { .. } | Expr::New { .. }) => "call_new",
        Some(Expr::Function { .. } | Expr::Arrow { .. } | Expr::Class { .. }) => {
            "function_arrow_class"
        }
        Some(Expr::Array { .. } | Expr::Object { .. }) => "object_array",
        Some(
            Expr::Parenthesized { .. }
            | Expr::Update { .. }
            | Expr::Unary { .. }
            | Expr::Binary { .. }
            | Expr::Conditional { .. }
            | Expr::Assign { .. }
            | Expr::Sequence { .. },
        ) => "operator",
        Some(Expr::Opaque { .. }) => "other",
    }
}

fn babel_default_variable_target_family(var: &VariableStatement) -> &'static str {
    let mut iter = var
        .declarators
        .iter()
        .map(|decl| babel_default_binding_pattern_family(&decl.target));
    let Some(first) = iter.next() else {
        return "empty";
    };
    if iter.all(|family| family == first) {
        first
    } else {
        "mixed"
    }
}

fn babel_default_variable_init_family(var: &VariableStatement) -> &'static str {
    let mut iter = var
        .declarators
        .iter()
        .map(|decl| babel_default_init_expr_family(decl.init.as_ref()));
    let Some(first) = iter.next() else {
        return "empty";
    };
    if iter.all(|family| family == first) {
        first
    } else {
        "mixed"
    }
}

fn babel_default_hot_init_variant(init: &Expr) -> &'static str {
    match init {
        Expr::Function { .. } => "function",
        Expr::Arrow { .. } => "arrow",
        Expr::Class { .. } => "class",
        _ => "other",
    }
}

