#[derive(Debug, Clone)]
struct EnclosingFrame {
    locals: Rc<Vec<LocalDescriptor>>,
    locals_name_index: Rc<LocalNameIndexSnapshot>,
    self_name_slot: Option<u16>,

    upvalues: Vec<UpvalueDescriptor>,
}

#[derive(Debug, Clone)]
enum LocalNameIndexSnapshot {
    Flat(std::collections::HashMap<String, u16>),
    Append {
        base: Rc<LocalNameIndexSnapshot>,
        name: String,
        slot: u16,
    },
}

impl LocalNameIndexSnapshot {
    const MAX_APPEND_DEPTH: usize = 64;

    fn from_locals(locals: &[LocalDescriptor]) -> Self {
        let mut index = std::collections::HashMap::with_capacity(locals.len());
        for (slot, local) in locals.iter().enumerate() {
            index.insert(local.name.clone(), slot as u16);
        }
        Self::Flat(index)
    }

    fn append(base: Rc<Self>, name: String, slot: u16) -> Self {
        Self::Append { base, name, slot }
    }

    fn append_depth(&self) -> usize {
        match self {
            Self::Flat(_) => 0,
            Self::Append { base, .. } => 1 + base.append_depth(),
        }
    }

    fn get(&self, name: &str) -> Option<u16> {
        match self {
            Self::Flat(index) => index.get(name).copied(),
            Self::Append {
                base,
                name: own_name,
                slot,
            } => {
                if own_name == name {
                    Some(*slot)
                } else {
                    base.get(name)
                }
            }
        }
    }
}

