    fn profile_pd123_flow_ts_hot_method_context(context: &str) -> bool {
        let in_hot_class = context.contains("class:FlowParserMixin>")
            || context.contains("class:TypeScriptParserMixin>");
        if !in_hot_class {
            return false;
        }
        [
            "flowParseObjectTypeProperty",
            "flowParseObjectType",
            "flowParsePrimaryType",
            "flowParseDeclare",
            "flowParseDeclareModule",
            "parseMaybeAssign",
            "parseConditional",
            "parseImportSpecifier",
            "tsParsePropertyOrMethodSignature",
            "parseStatementContent",
            "parseSubscript",
            "parseTypeOnlyImportExportSpecifier",
            "tsParseTupleElementType",
            "tsParseModifiers",
            "fillOptionalPropertiesForTSESLint",
        ]
        .iter()
        .any(|method| context.ends_with(&format!(":{}", method)))
    }

