    fn babel_var_arrow_return_arg_family(e: &Expr) -> &'static str {
        match e {
            Expr::Function { name: None, .. } => "function",
            Expr::Arrow { .. } => "arrow",
            Expr::Class { name: None, .. } => "class",
            Expr::Parenthesized { .. } => "parenthesized",
            Expr::NullLiteral { .. }
            | Expr::BoolLiteral { .. }
            | Expr::NumberLiteral { .. }
            | Expr::BigIntLiteral { .. }
            | Expr::StringLiteral { .. }
            | Expr::WtfStringLiteral { .. }
            | Expr::RegExp { .. }
            | Expr::TemplateObject { .. } => "literal",
            Expr::Identifier { .. }
            | Expr::This { .. }
            | Expr::Super { .. }
            | Expr::MetaProperty { .. } => "identifier",
            Expr::Member { .. } => "member",
            Expr::Call { .. } | Expr::New { .. } => "call_new",
            Expr::Array { .. } | Expr::Object { .. } => "object_array",
            Expr::Unary { .. }
            | Expr::Update { .. }
            | Expr::Binary { .. }
            | Expr::Conditional { .. }
            | Expr::Assign { .. }
            | Expr::Sequence { .. } => "operator",
            Expr::Function { name: Some(_), .. } => "named_function",
            Expr::Class { name: Some(_), .. } => "named_class",
            Expr::TemplateLiteral { .. } => "template_literal",
            Expr::Opaque { .. } => "opaque",
        }
    }

