    fn function_body_call_route_profile_counters(
        callee_ref: &Expr,
        arguments: &[Argument],
        call_optional: bool,
    ) -> (
        &'static std::sync::atomic::AtomicU64,
        &'static std::sync::atomic::AtomicU64,
    ) {
        use crate::compile_profile as cp;
        if matches!(callee_ref, Expr::Super { .. }) {
            return (
                &cp::FUNCTION_BODY_CALL_ROUTE_SUPER_NS,
                &cp::FUNCTION_BODY_CALL_ROUTE_SUPER_CALLS,
            );
        }
        if let Expr::Member { object, .. } = callee_ref {
            if matches!(object.as_ref(), Expr::Super { .. }) {
                return (
                    &cp::FUNCTION_BODY_CALL_ROUTE_SUPER_MEMBER_NS,
                    &cp::FUNCTION_BODY_CALL_ROUTE_SUPER_MEMBER_CALLS,
                );
            }
            return (
                &cp::FUNCTION_BODY_CALL_ROUTE_METHOD_NS,
                &cp::FUNCTION_BODY_CALL_ROUTE_METHOD_CALLS,
            );
        }
        if call_optional || Self::args_has_spread(arguments) || arguments.len() > 255 {
            (
                &cp::FUNCTION_BODY_CALL_ROUTE_SPREAD_APPLY_NS,
                &cp::FUNCTION_BODY_CALL_ROUTE_SPREAD_APPLY_CALLS,
            )
        } else {
            (
                &cp::FUNCTION_BODY_CALL_ROUTE_PLAIN_NS,
                &cp::FUNCTION_BODY_CALL_ROUTE_PLAIN_CALLS,
            )
        }
    }

