    fn var_init_expr_profile_counters(
        e: &Expr,
    ) -> (
        &'static std::sync::atomic::AtomicU64,
        &'static std::sync::atomic::AtomicU64,
    ) {
        use crate::compile_profile as cp;
        match e {
            Expr::Function { name: None, .. } => {
                (&cp::VAR_INIT_FUNCTION_NS, &cp::VAR_INIT_FUNCTION_CALLS)
            }
            Expr::Arrow { .. } => (&cp::VAR_INIT_ARROW_NS, &cp::VAR_INIT_ARROW_CALLS),
            Expr::Class { name: None, .. } => (&cp::VAR_INIT_CLASS_NS, &cp::VAR_INIT_CLASS_CALLS),
            Expr::Parenthesized { .. } => (&cp::VAR_INIT_PAREN_NS, &cp::VAR_INIT_PAREN_CALLS),
            Expr::NullLiteral { .. }
            | Expr::BoolLiteral { .. }
            | Expr::NumberLiteral { .. }
            | Expr::BigIntLiteral { .. }
            | Expr::StringLiteral { .. }
            | Expr::WtfStringLiteral { .. }
            | Expr::RegExp { .. }
            | Expr::TemplateObject { .. } => {
                (&cp::VAR_INIT_LITERAL_NS, &cp::VAR_INIT_LITERAL_CALLS)
            }
            Expr::Identifier { .. }
            | Expr::This { .. }
            | Expr::Super { .. }
            | Expr::MetaProperty { .. } => {
                (&cp::VAR_INIT_IDENTIFIER_NS, &cp::VAR_INIT_IDENTIFIER_CALLS)
            }
            Expr::Member { .. } => (&cp::VAR_INIT_MEMBER_NS, &cp::VAR_INIT_MEMBER_CALLS),
            Expr::Call { .. } | Expr::New { .. } => {
                (&cp::VAR_INIT_CALL_NS, &cp::VAR_INIT_CALL_CALLS)
            }
            Expr::Array { .. } | Expr::Object { .. } => (
                &cp::VAR_INIT_OBJECT_ARRAY_NS,
                &cp::VAR_INIT_OBJECT_ARRAY_CALLS,
            ),
            Expr::Unary { .. }
            | Expr::Update { .. }
            | Expr::Binary { .. }
            | Expr::Conditional { .. }
            | Expr::Assign { .. }
            | Expr::Sequence { .. } => (&cp::VAR_INIT_OPERATOR_NS, &cp::VAR_INIT_OPERATOR_CALLS),
            Expr::Function { name: Some(_), .. }
            | Expr::Class { name: Some(_), .. }
            | Expr::TemplateLiteral { .. }
            | Expr::Opaque { .. } => (&cp::VAR_INIT_OTHER_NS, &cp::VAR_INIT_OTHER_CALLS),
        }
    }

    fn emit_destructure(
        &mut self,
        pat: &rusty_js_ast::BindingPattern,
        src_slot: u16,
    ) -> Result<(), CompileError> {
        match pat {
            rusty_js_ast::BindingPattern::Identifier(id) => {
                let slot = self
                    .resolve_local(&id.name)
                    .expect("destructure leaf: binding slot pre-allocated by caller");
                encode_op(&mut self.bytecode, Op::LoadLocal);
                encode_u16(&mut self.bytecode, src_slot);

                encode_op(&mut self.bytecode, Op::InitLocal);
                encode_u16(&mut self.bytecode, slot);
            }
            rusty_js_ast::BindingPattern::Array(arr) => {

                let iter_slot = self.alloc_temp("<destr.iter>");
                let done_slot = self.alloc_temp("<destr.iter.done>");
                let open_idx = self
                    .constants
                    .intern(Constant::String("__destr_iter_open".into()));
                encode_op(&mut self.bytecode, Op::LoadGlobal);
                encode_u16(&mut self.bytecode, open_idx);
                encode_op(&mut self.bytecode, Op::LoadLocal);
                encode_u16(&mut self.bytecode, src_slot);
                encode_op(&mut self.bytecode, Op::Call);
                encode_u8(&mut self.bytecode, 1);
                encode_op(&mut self.bytecode, Op::StoreLocal);
                encode_u16(&mut self.bytecode, iter_slot);

                encode_op(&mut self.bytecode, Op::PushFalse);
                encode_op(&mut self.bytecode, Op::StoreLocal);
                encode_u16(&mut self.bytecode, done_slot);
                for slot_opt in arr.elements.iter() {
                    self.emit_iter_step_value(iter_slot, Some(done_slot))?;
                    match slot_opt {
                        Some(elem) => {
                            self.emit_element_with_default(&elem.target, elem.default.as_ref())?
                        }
                        None => {
                            encode_op(&mut self.bytecode, Op::Pop);
                        }
                    }
                }
                if let Some(rest_pat) = &arr.rest {
                    self.emit_destructure_rest_array(iter_slot, Some(done_slot));
                    self.emit_element_with_default(rest_pat, None)?;

                } else {

                    self.emit_iter_close_if_not_done(iter_slot, done_slot)?;
                }
            }
            rusty_js_ast::BindingPattern::Object(obj) => {
                self.emit_destructure_object_check(src_slot);
                let excluded_slot = self.alloc_temp("<destr.object.excluded>");
                let mut excluded_len: u32 = 0;
                encode_op(&mut self.bytecode, Op::NewArray);
                encode_u16(&mut self.bytecode, 0);
                encode_op(&mut self.bytecode, Op::InitLocal);
                encode_u16(&mut self.bytecode, excluded_slot);
                for prop in &obj.properties {
                    let with_binding_target = match &prop.value.target {
                        rusty_js_ast::BindingPattern::Identifier(id)
                            if self.should_route_identifier_through_with(&id.name) =>
                        {
                            self.note_with_fallback_binding(&id.name);
                            let idx = self.constants.intern(Constant::String(id.name.clone()));
                            let base_slot = self.alloc_temp("<destr.with.base>");
                            Some((id.name.clone(), idx, base_slot))
                        }
                        _ => None,
                    };

                    encode_op(&mut self.bytecode, Op::LoadLocal);
                    encode_u16(&mut self.bytecode, src_slot);
                    match &prop.key {
                        rusty_js_ast::PropertyKey::Identifier(id) => {
                            let k = self.constants.intern(Constant::String(id.name.clone()));
                            encode_op(&mut self.bytecode, Op::PushConst);
                            encode_u16(&mut self.bytecode, k);
                            self.emit_object_rest_exclusion_append(
                                excluded_slot,
                                &mut excluded_len,
                            );
                            if let Some((_, idx, base_slot)) = &with_binding_target {
                                encode_op(&mut self.bytecode, Op::ResolveWithName);
                                encode_u16(&mut self.bytecode, *idx);
                                encode_op(&mut self.bytecode, Op::StoreLocal);
                                encode_u16(&mut self.bytecode, *base_slot);
                            }
                            encode_op(&mut self.bytecode, Op::GetProp);
                            encode_u16(&mut self.bytecode, k);
                        }
                        rusty_js_ast::PropertyKey::String(s) => {
                            let k = self.constants.intern(Constant::String((**s).clone()));
                            encode_op(&mut self.bytecode, Op::PushConst);
                            encode_u16(&mut self.bytecode, k);
                            self.emit_object_rest_exclusion_append(
                                excluded_slot,
                                &mut excluded_len,
                            );
                            if let Some((_, idx, base_slot)) = &with_binding_target {
                                encode_op(&mut self.bytecode, Op::ResolveWithName);
                                encode_u16(&mut self.bytecode, *idx);
                                encode_op(&mut self.bytecode, Op::StoreLocal);
                                encode_u16(&mut self.bytecode, *base_slot);
                            }
                            encode_op(&mut self.bytecode, Op::GetProp);
                            encode_u16(&mut self.bytecode, k);
                        }
                        rusty_js_ast::PropertyKey::Number(n) => {
                            let name = number_property_key(*n);
                            let k = self.constants.intern(Constant::String(name.clone()));
                            encode_op(&mut self.bytecode, Op::PushConst);
                            encode_u16(&mut self.bytecode, k);
                            self.emit_object_rest_exclusion_append(
                                excluded_slot,
                                &mut excluded_len,
                            );
                            if let Some((_, idx, base_slot)) = &with_binding_target {
                                encode_op(&mut self.bytecode, Op::ResolveWithName);
                                encode_u16(&mut self.bytecode, *idx);
                                encode_op(&mut self.bytecode, Op::StoreLocal);
                                encode_u16(&mut self.bytecode, *base_slot);
                            }
                            encode_op(&mut self.bytecode, Op::GetProp);
                            encode_u16(&mut self.bytecode, k);
                        }
                        rusty_js_ast::PropertyKey::Computed(expr) => {

                            self.compile_expr(expr)?;
                            encode_op(&mut self.bytecode, Op::ToPropertyKey);
                            encode_op(&mut self.bytecode, Op::Dup);
                            self.emit_object_rest_exclusion_append(
                                excluded_slot,
                                &mut excluded_len,
                            );
                            if let Some((_, idx, base_slot)) = &with_binding_target {
                                encode_op(&mut self.bytecode, Op::ResolveWithName);
                                encode_u16(&mut self.bytecode, *idx);
                                encode_op(&mut self.bytecode, Op::StoreLocal);
                                encode_u16(&mut self.bytecode, *base_slot);
                            }
                            encode_op(&mut self.bytecode, Op::GetIndex);
                        }
                    }
                    if let Some((name, idx, base_slot)) = with_binding_target {
                        self.emit_element_with_default_to_resolved_with(
                            &name,
                            idx,
                            base_slot,
                            prop.value.default.as_ref(),
                        )?;
                    } else {
                        self.emit_element_with_default(
                            &prop.value.target,
                            prop.value.default.as_ref(),
                        )?;
                    }
                }
                if let Some(rest_id) = &obj.rest {

                    let name_idx = self
                        .constants
                        .intern(Constant::String("__destr_object_rest".into()));
                    encode_op(&mut self.bytecode, Op::LoadGlobal);
                    encode_u16(&mut self.bytecode, name_idx);
                    encode_op(&mut self.bytecode, Op::LoadLocal);
                    encode_u16(&mut self.bytecode, src_slot);
                    encode_op(&mut self.bytecode, Op::LoadLocal);
                    encode_u16(&mut self.bytecode, excluded_slot);
                    encode_op(&mut self.bytecode, Op::Call);
                    encode_u8(&mut self.bytecode, 2);
                    let slot = self
                        .resolve_local(&rest_id.name)
                        .expect("object-rest binding slot pre-allocated by caller");

                    encode_op(&mut self.bytecode, Op::InitLocal);
                    encode_u16(&mut self.bytecode, slot);
                }
            }
        }
        Ok(())
    }

    fn emit_destructure_rest_array(&mut self, iter_slot: u16, done_slot: Option<u16>) {
        let mut done_skip_end: Option<usize> = None;
        if let Some(slot) = done_slot {
            encode_op(&mut self.bytecode, Op::LoadLocal);
            encode_u16(&mut self.bytecode, slot);
            let j_not_done = self.emit_jump(Op::JumpIfFalse);
            encode_op(&mut self.bytecode, Op::NewArray);
            encode_u16(&mut self.bytecode, 0);
            done_skip_end = Some(self.emit_jump(Op::Jump));
            self.patch_jump(j_not_done);
        }
        let rest_idx = self
            .constants
            .intern(Constant::String("__destr_iter_rest".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, rest_idx);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, iter_slot);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);
        if let Some(j_end) = done_skip_end {
            self.patch_jump(j_end);
        }
    }

    fn emit_iter_step_value(
        &mut self,
        iter_slot: u16,
        done_slot: Option<u16>,
    ) -> Result<(), CompileError> {
        let mut done_skip_end: Option<usize> = None;
        if let Some(slot) = done_slot {
            encode_op(&mut self.bytecode, Op::LoadLocal);
            encode_u16(&mut self.bytecode, slot);
            let j_not_done = self.emit_jump(Op::JumpIfFalse);
            encode_op(&mut self.bytecode, Op::PushUndef);
            done_skip_end = Some(self.emit_jump(Op::Jump));
            self.patch_jump(j_not_done);
        }
        let step_idx = self
            .constants
            .intern(Constant::String("__destr_iter_step".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, step_idx);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, iter_slot);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);

        encode_op(&mut self.bytecode, Op::Dup);
        let done_key = self.constants.intern(Constant::String("done".into()));
        encode_op(&mut self.bytecode, Op::GetProp);
        encode_u16(&mut self.bytecode, done_key);

        if let Some(slot) = done_slot {
            encode_op(&mut self.bytecode, Op::Dup);
            encode_op(&mut self.bytecode, Op::StoreLocal);
            encode_u16(&mut self.bytecode, slot);

        }
        let j_done = self.emit_jump(Op::JumpIfTrue);

        let value_key = self.constants.intern(Constant::String("value".into()));
        encode_op(&mut self.bytecode, Op::GetProp);
        encode_u16(&mut self.bytecode, value_key);
        let j_end = self.emit_jump(Op::Jump);

        self.patch_jump(j_done);
        encode_op(&mut self.bytecode, Op::Pop);
        encode_op(&mut self.bytecode, Op::PushUndef);
        self.patch_jump(j_end);
        if let Some(j_end) = done_skip_end {
            self.patch_jump(j_end);
        }
        Ok(())
    }

    fn emit_iter_close_call(&mut self, iter_slot: u16) {
        let close_idx = self
            .constants
            .intern(Constant::String("__destr_iter_close".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, close_idx);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, iter_slot);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);
        encode_op(&mut self.bytecode, Op::Pop);
    }

    fn emit_iter_close_call_await(&mut self, iter_slot: u16) {
        let close_idx = self
            .constants
            .intern(Constant::String("__destr_iter_close".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, close_idx);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, iter_slot);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);

        let await_tmp = self.alloc_temp("<for-await.close.await>");
        encode_op(&mut self.bytecode, Op::StoreLocal);
        encode_u16(&mut self.bytecode, await_tmp);
        let await_nm = self.constants.intern(Constant::String("__await".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, await_nm);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, await_tmp);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);
        encode_op(&mut self.bytecode, Op::Pop);
    }

    fn emit_loop_iteration_completion_reset(&mut self) {
        if let Some(stash) = self.eval_completion_global.clone() {
            let idx = self.constants.intern(Constant::String(stash));
            encode_op(&mut self.bytecode, Op::PushUndef);
            encode_op(&mut self.bytecode, Op::StoreGlobal);
            encode_u16(&mut self.bytecode, idx);
        }
    }

    fn compile_loop_reentered_body(&mut self, body: &Stmt) -> Result<(), CompileError> {
        let needs_fresh_block_lexicals =
            stmt_contains_closure(body) || stmt_contains_direct_eval(body);
        if needs_fresh_block_lexicals {
            self.loop_reentered_block_freshness_depth += 1;
        }
        let result = self.compile_stmt(body);
        if needs_fresh_block_lexicals {
            self.loop_reentered_block_freshness_depth -= 1;
        }
        result
    }

    fn compile_finalizer_stmt(&mut self, fin: &Stmt) -> Result<(), CompileError> {
        if let Some(stash) = self.eval_completion_global.clone() {
            let idx = self.constants.intern(Constant::String(stash));
            encode_op(&mut self.bytecode, Op::PushUndef);
            encode_op(&mut self.bytecode, Op::StoreGlobal);
            encode_u16(&mut self.bytecode, idx);
        }
        self.compile_stmt(fin)
    }

    fn compile_finalizer_stmt_preserving_completion(
        &mut self,
        fin: &Stmt,
    ) -> Result<(), CompileError> {
        if let Some(stash) = self.eval_completion_global.clone() {
            let temp = format!("__cruft_fin_cv_{}", self.bytecode.len());
            let stash_idx = self.constants.intern(Constant::String(stash));
            let temp_idx = self.constants.intern(Constant::String(temp));
            encode_op(&mut self.bytecode, Op::LoadGlobalOrUndef);
            encode_u16(&mut self.bytecode, stash_idx);
            encode_op(&mut self.bytecode, Op::StoreGlobal);
            encode_u16(&mut self.bytecode, temp_idx);
            self.compile_finalizer_stmt(fin)?;
            encode_op(&mut self.bytecode, Op::LoadGlobalOrUndef);
            encode_u16(&mut self.bytecode, temp_idx);
            encode_op(&mut self.bytecode, Op::StoreGlobal);
            encode_u16(&mut self.bytecode, stash_idx);
            Ok(())
        } else {
            self.compile_finalizer_stmt(fin)
        }
    }

    fn emit_iter_close_dispatch(&mut self, iter_slot: u16, is_await: bool) {
        if is_await {
            self.emit_iter_close_call_await(iter_slot);
        } else {
            self.emit_iter_close_call(iter_slot);
        }
    }

    fn emit_iter_close_if_not_done(
        &mut self,
        iter_slot: u16,
        done_slot: u16,
    ) -> Result<(), CompileError> {

        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, done_slot);
        let j_skip = self.emit_jump(Op::JumpIfTrue);
        let close_idx = self
            .constants
            .intern(Constant::String("__destr_iter_close".into()));
        encode_op(&mut self.bytecode, Op::LoadGlobal);
        encode_u16(&mut self.bytecode, close_idx);
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, iter_slot);
        encode_op(&mut self.bytecode, Op::Call);
        encode_u8(&mut self.bytecode, 1);
        encode_op(&mut self.bytecode, Op::Pop);
        self.patch_jump(j_skip);
        Ok(())
    }

    fn emit_element_with_default(
        &mut self,
        target: &rusty_js_ast::BindingPattern,
        default: Option<&Expr>,
    ) -> Result<(), CompileError> {
        if let Some(def_expr) = default {

            encode_op(&mut self.bytecode, Op::Dup);
            encode_op(&mut self.bytecode, Op::PushUndef);
            encode_op(&mut self.bytecode, Op::StrictEq);
            let j_skip = self.emit_jump(Op::JumpIfFalse);
            encode_op(&mut self.bytecode, Op::Pop);

            let name_hint = if let rusty_js_ast::BindingPattern::Identifier(id) = target {
                Some(id.name.as_str())
            } else {
                None
            };
            if name_hint.is_some() {
                self.compile_expr_with_name_hint(def_expr, name_hint)?;
            } else {
                self.compile_expr(def_expr)?;
            }
            self.patch_jump(j_skip);
        }
        match target {
            rusty_js_ast::BindingPattern::Identifier(id) => {
                let slot = self
                    .resolve_local(&id.name)
                    .expect("destructure leaf: binding slot pre-allocated by caller");

                encode_op(&mut self.bytecode, Op::InitLocal);
                encode_u16(&mut self.bytecode, slot);
            }
            nested => {
                let tmp = self.alloc_temp("<destr.tmp>");
                encode_op(&mut self.bytecode, Op::StoreLocal);
                encode_u16(&mut self.bytecode, tmp);
                self.emit_destructure(nested, tmp)?;
            }
        }
        Ok(())
    }

    fn emit_element_with_default_to_resolved_with(
        &mut self,
        name: &str,
        name_idx: u16,
        base_slot: u16,
        default: Option<&Expr>,
    ) -> Result<(), CompileError> {
        if let Some(def_expr) = default {
            encode_op(&mut self.bytecode, Op::Dup);
            encode_op(&mut self.bytecode, Op::PushUndef);
            encode_op(&mut self.bytecode, Op::StrictEq);
            let j_skip = self.emit_jump(Op::JumpIfFalse);
            encode_op(&mut self.bytecode, Op::Pop);
            self.compile_expr_with_name_hint(def_expr, Some(name))?;
            self.patch_jump(j_skip);
        }
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, base_slot);
        encode_op(&mut self.bytecode, Op::Swap);
        encode_op(&mut self.bytecode, Op::StoreWithNameRef);
        encode_u16(&mut self.bytecode, name_idx);
        encode_op(&mut self.bytecode, Op::Pop);
        Ok(())
    }

    fn emit_jump(&mut self, op: Op) -> usize {
        encode_op(&mut self.bytecode, op);
        let operand_off = self.bytecode.len();
        encode_i32(&mut self.bytecode, 0);
        operand_off
    }

    fn emit_delete_opt_guard(&mut self, active: bool) -> Vec<usize> {
        if !active {
            return Vec::new();
        }
        let mut sinks = Vec::new();
        encode_op(&mut self.bytecode, Op::Dup);
        encode_op(&mut self.bytecode, Op::PushUndef);
        encode_op(&mut self.bytecode, Op::StrictEq);
        sinks.push(self.emit_jump(Op::JumpIfTrue));
        encode_op(&mut self.bytecode, Op::Dup);
        encode_op(&mut self.bytecode, Op::PushNull);
        encode_op(&mut self.bytecode, Op::StrictEq);
        sinks.push(self.emit_jump(Op::JumpIfTrue));
        sinks
    }

    fn finish_delete_opt_guard(&mut self, sinks: Vec<usize>) {
        if sinks.is_empty() {
            return;
        }
        let end = self.emit_jump(Op::Jump);
        for site in sinks {
            self.patch_jump_at(site);
        }
        encode_op(&mut self.bytecode, Op::Pop);
        encode_op(&mut self.bytecode, Op::PushTrue);
        self.patch_jump_at(end);
    }

    fn patch_jump(&mut self, operand_off: usize) {
        let here = self.bytecode.len() as i32;
        let from = (operand_off + 4) as i32;
        let disp = here - from;
        self.bytecode[operand_off..operand_off + 4].copy_from_slice(&disp.to_le_bytes());
    }

    fn patch_jump_at(&mut self, operand_off: usize) {
        self.patch_jump(operand_off);
    }

    fn patch_jump_to(&mut self, operand_off: usize, target: usize) {
        let from = (operand_off + 4) as i32;
        let disp = target as i32 - from;
        self.bytecode[operand_off..operand_off + 4].copy_from_slice(&disp.to_le_bytes());
    }

    fn emit_back_jump(&mut self, target: usize) {
        encode_op(&mut self.bytecode, Op::Jump);
        let from = (self.bytecode.len() + 4) as i32;
        let disp = target as i32 - from;
        encode_i32(&mut self.bytecode, disp);
    }

    fn alloc_local(&mut self, mut desc: LocalDescriptor) -> u16 {

        desc.top_level_lexical =
            self.block_depth == 0 && matches!(desc.kind, VariableKind::Let | VariableKind::Const);
        desc.script_global_var = self.block_depth == 0
            && self.script_var_env_is_global()
            && !self.script_var_deletable
            && matches!(desc.kind, VariableKind::Var);
        let idx = self.locals.len();
        assert!(idx < u16::MAX as usize, "too many locals");
        let index_name = desc.name.clone();
        self.locals.push(desc);
        self.invalidate_locals_vector_snapshot();
        self.append_local_to_name_index_snapshot(index_name, idx as u16);
        idx as u16
    }

    fn emit_object_rest_exclusion_append(&mut self, excluded_slot: u16, excluded_len: &mut u32) {
        encode_op(&mut self.bytecode, Op::LoadLocal);
        encode_u16(&mut self.bytecode, excluded_slot);
        encode_op(&mut self.bytecode, Op::Swap);
        encode_op(&mut self.bytecode, Op::InitIndex);
        encode_u32(&mut self.bytecode, *excluded_len);
        encode_op(&mut self.bytecode, Op::Pop);
        *excluded_len += 1;
    }

    fn resolve_local(&mut self, name: &str) -> Option<u16> {
        self.locals_name_index_snapshot().get(name)
    }

    fn profile_pd123_prefix_creator_target(&self, name: &str) -> bool {
        crate::compile_profile::enabled()
            && self
                .profile_pd123_proto_context
                .as_deref()
                .is_some_and(|ctx| {
                    matches!(
                        (ctx, name),
                        (
                            "named-class-method:method:getScopeHandler",
                            "FlowScopeHandler"
                        ) | ("named-class-method:method:addComment", "FLOW_PRAGMA_REGEX")
                            | ("named-class-method:method:flowParsePredicate", "FlowErrors")
                            | (
                                "named-class-method:method:checkReservedType",
                                "reservedTypes"
                            )
                            | ("named-class-method:method:flowInTopLevelContext", "types")
                            | ("named-class-method:method:parseMaybeAssign", "FlowErrors")
                            | ("named-class-method:method:parseMaybeAssign", "types")
                    ) || (ctx.contains("flowParseDeclareModule") && name == "isEsModuleType")
                })
    }

    fn profile_source_line_excerpt(&self, span: Span) -> String {
        let src = self.source_text.as_ref();
        let start = span.start.min(src.len());
        let end = span.end.min(src.len());
        if start > end {
            return "<invalid-span>".to_string();
        }
        let line_start = src[..start].rfind('\n').map(|idx| idx + 1).unwrap_or(0);
        let line_end = src[end..]
            .find('\n')
            .map(|idx| end + idx)
            .unwrap_or_else(|| src.len());
        src[line_start..line_end]
            .chars()
            .take(260)
            .collect::<String>()
            .escape_debug()
            .to_string()
    }

    fn profile_pd123_detail_rows_enabled() -> bool {
        std::env::var_os("CRUFT_PROFILE_PD123_DETAIL_ROWS").is_some_and(|v| v != "0")
    }

    fn profile_pd123_branch_clause_rows_enabled() -> bool {
        std::env::var_os("CRUFT_PROFILE_PD123_BRANCH_CLAUSE_ROWS").is_some_and(|v| v != "0")
    }

