    fn note_with_fallback_binding(&mut self, name: &str) {
        if self.resolve_local(name).is_none() {
            let _ = self.resolve_upvalue(name);
        }
    }

    fn profile_upvalue_prefix(
        upvalues: &[UpvalueDescriptor],
        terminal_locals: Option<&[LocalDescriptor]>,
        take: usize,
    ) -> String {
        upvalues
            .iter()
            .take(take)
            .enumerate()
            .map(|(idx, desc)| {
                let terminal = match desc.source {
                    UpvalueSource::Local(slot) => {
                        let terminal_name = terminal_locals
                            .and_then(|locals| locals.get(slot as usize))
                            .map(|local| local.name.as_str())
                            .unwrap_or("<missing>");
                        format!("terminal_local={slot}:{terminal_name}")
                    }
                    UpvalueSource::Upvalue(up) => {
                        format!("terminal_upvalue={up}")
                    }
                };
                format!(
                    "{}:{}:{:?}:self={}:{}",
                    idx, desc.name, desc.source, desc.is_fn_self_name, terminal
                )
            })
            .collect::<Vec<_>>()
            .join("|")
    }

    fn active_with_depth(&self) -> u32 {
        self.with_depth.saturating_sub(self.inherited_with_depth)
    }

    fn local_declared_inside_active_with(&mut self, name: &str) -> bool {
        let Some(snapshot) = self.with_local_snapshots.last().copied() else {
            return false;
        };
        self.resolve_local(name)
            .is_some_and(|slot| (slot as usize) >= snapshot)
    }

    fn should_route_identifier_through_with(&mut self, name: &str) -> bool {
        self.with_depth > 0
            && !self.local_declared_inside_active_with(name)
            && (self.active_with_depth() > 0 || self.resolve_local(name).is_none())
    }

    fn compile_expr_with_name_hint(
        &mut self,
        e: &Expr,
        hint: Option<&str>,
    ) -> Result<(), CompileError> {
        let prof = crate::compile_profile::enabled();
        let t_hint = prof.then(std::time::Instant::now);
        let (hint_ns, hint_calls) = Self::hint_expr_profile_counters(e);
        let result = match e {
            Expr::Function {
                name: None,
                is_async,
                is_generator,
                is_method,
                params,
                body,
                span,
            } => {
                self.record_span(*span);
                if !*is_async
                    && !*is_generator
                    && !*is_method
                    && self.try_emit_lazy_simple_ordinary_function(None, hint, params, body, *span)
                {
                    self.next_compile_source_span = None;
                    return Ok(());
                }
                self.next_compile_source_span = Some(*span);

                self.next_compile_is_method = *is_method;
                let prof = crate::compile_profile::enabled();
                let profile_function_body_assign_member_value_function =
                    self.profile_function_body_assign_member_value_function_proto;
                let profile_plain_call_arg_proto_body_var_init_call_callee_function_proto =
                    self.profile_function_body_plain_call_arg_function_proto_body_var_init_call_callee_function_proto;
                let t_proto = prof.then(std::time::Instant::now);
                let profile_babel_parser_default_function_proto_direct = prof
                    && hint == Some("default")
                    && std::env::var("CRUFT_CJS_WRAPPER_PHASE_PROFILE_FILTER")
                        .ok()
                        .filter(|filter| !filter.is_empty())
                        .is_some_and(|filter| self.source_url.contains(&filter));
                let old_babel_default_proto_profile =
                    self.profile_babel_parser_default_function_proto_direct;
                if profile_babel_parser_default_function_proto_direct {
                    self.profile_babel_parser_default_function_proto_direct = true;
                }
                let proto = self.compile_function_proto_with_name_hint(
                    None,
                    hint,
                    FunctionSelfNameMode::Expression,
                    *is_async,
                    *is_generator,
                    params,
                    body,
                )?;
                self.profile_babel_parser_default_function_proto_direct =
                    old_babel_default_proto_profile;
                if let Some(t) = t_proto {
                    let elapsed = t.elapsed().as_nanos() as u64;
                    crate::compile_profile::add(
                        &crate::compile_profile::NAME_HINT_FUNCTION_PROTO_NS,
                        elapsed,
                    );
                    if profile_function_body_assign_member_value_function {
                        crate::compile_profile::add(
                            &crate::compile_profile::FUNCTION_BODY_ASSIGN_EXPR_STMT_MEMBER_VALUE_FUNCTION_OUTER_PROTO_NS,
                            elapsed,
                        );
                        crate::compile_profile::inc(
                            &crate::compile_profile::FUNCTION_BODY_ASSIGN_EXPR_STMT_MEMBER_VALUE_FUNCTION_OUTER_PROTO_CALLS,
                        );
                    }
                }
                let t_emit = prof.then(std::time::Instant::now);
                let captures = proto.upvalues.clone();
                let idx = self
                    .constants
                    .intern(Constant::Function(std::rc::Rc::new(proto)));
                encode_op(&mut self.bytecode, Op::MakeClosure);
                encode_u16(&mut self.bytecode, idx);
                emit_captures(&mut self.bytecode, &captures);
                if let Some(t) = t_emit {
                    let elapsed = t.elapsed().as_nanos() as u64;
                    crate::compile_profile::add(
                        &crate::compile_profile::NAME_HINT_FUNCTION_INTERN_EMIT_NS,
                        elapsed,
                    );
                    if profile_plain_call_arg_proto_body_var_init_call_callee_function_proto {
                        crate::compile_profile::add(
                            &crate::compile_profile::FUNCTION_BODY_PLAIN_CALL_ARG_FUNCTION_PROTO_BODY_STMT_VAR_INIT_CALL_CALLEE_FUNCTION_INTERN_EMIT_NS,
                            elapsed,
                        );
                        crate::compile_profile::inc(
                            &crate::compile_profile::FUNCTION_BODY_PLAIN_CALL_ARG_FUNCTION_PROTO_BODY_STMT_VAR_INIT_CALL_CALLEE_FUNCTION_INTERN_EMIT_CALLS,
                        );
                    }
                    if profile_function_body_assign_member_value_function {
                        crate::compile_profile::add(
                            &crate::compile_profile::FUNCTION_BODY_ASSIGN_EXPR_STMT_MEMBER_VALUE_FUNCTION_OUTER_INTERN_EMIT_NS,
                            elapsed,
                        );
                        crate::compile_profile::inc(
                            &crate::compile_profile::FUNCTION_BODY_ASSIGN_EXPR_STMT_MEMBER_VALUE_FUNCTION_OUTER_INTERN_EMIT_CALLS,
                        );
                    }
                }
                Ok(())
            }
            Expr::Arrow {
                is_async,
                params,
                body,
                span,
            } => {
                let prof = crate::compile_profile::enabled();
                let profile_member_arg_arrow = std::mem::take(&mut self.profile_arrow_return_named_class_method_if_consequent_block_body_static_member_rhs_member_call_arg_arrow);
                let t_emit = prof.then(std::time::Instant::now);
                let (idx, captures) = self.compile_arrow_function_payload(
                    *is_async,
                    params,
                    body,
                    *span,
                    hint,
                    profile_member_arg_arrow,
                )?;
                encode_op(&mut self.bytecode, Op::MakeArrow);
                encode_u16(&mut self.bytecode, idx);
                emit_captures(&mut self.bytecode, &captures);
                if let Some(t0) = t_emit {
                    let elapsed = t0.elapsed().as_nanos() as u64;
                    crate::compile_profile::add(
                        &crate::compile_profile::ARROW_MAKE_EMIT_NS,
                        elapsed,
                    );
                    crate::compile_profile::inc(&crate::compile_profile::ARROW_MAKE_EMIT_CALLS);
                    if profile_member_arg_arrow {
                        crate::compile_profile::add(
                            &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_MAKE_EMIT_NS,
                            elapsed,
                        );
                        crate::compile_profile::inc(
                            &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_MAKE_EMIT_CALLS,
                        );
                    }
                }
                Ok(())
            }
            Expr::Class {
                decorators: _,
                name: None,
                super_class,
                members,
                span,
            } => {
                self.record_span(*span);
                self.compile_class_with_name_hint(
                    *span,
                    None,
                    hint,
                    super_class.as_ref().map(|b| b.as_ref()),
                    members,
                )
            }
            Expr::Parenthesized { expr, .. } => self.compile_expr_with_name_hint(expr, hint),
            _ => self.compile_expr(e),
        };
        if let Some(t0) = t_hint {
            crate::compile_profile::add(hint_ns, t0.elapsed().as_nanos() as u64);
            crate::compile_profile::inc(hint_calls);
        }
        result
    }

    fn compile_arrow_function_payload(
        &mut self,
        is_async: bool,
        params: &[Parameter],
        body: &ArrowBody,
        span: Span,
        hint: Option<&str>,
        profile_member_arg_arrow: bool,
    ) -> Result<(u16, Vec<UpvalueDescriptor>), CompileError> {
        self.record_span(span);
        self.next_compile_source_span = Some(span);
        let prof = crate::compile_profile::enabled();
        let babel_var_arrow_name = self
            .profile_babel_parser_default_var_arrow_init_name
            .clone();
        let profile_babel_var_arrow = prof && babel_var_arrow_name.is_some();
        let t_babel_var_arrow_payload_total = profile_babel_var_arrow.then(std::time::Instant::now);
        let mut babel_var_arrow_normalize_ns = 0_u64;
        let mut babel_var_arrow_proto_ns = 0_u64;
        let mut babel_var_arrow_capture_ns = 0_u64;
        let mut babel_var_arrow_intern_ns = 0_u64;
        let t_normalize = prof.then(std::time::Instant::now);
        let body_stmts: Vec<Stmt> = match body {
            ArrowBody::Block(stmts) => stmts.clone(),
            ArrowBody::Expression(expr) => vec![Stmt::Return {
                argument: Some((**expr).clone()),
                span: expr.span(),
            }],
        };
        if let Some(t0) = t_normalize {
            let elapsed = t0.elapsed().as_nanos() as u64;
            if profile_babel_var_arrow {
                babel_var_arrow_normalize_ns = elapsed;
            }
            crate::compile_profile::add(&crate::compile_profile::ARROW_BODY_NORMALIZE_NS, elapsed);
            crate::compile_profile::inc(&crate::compile_profile::ARROW_BODY_NORMALIZE_CALLS);
            if profile_member_arg_arrow {
                crate::compile_profile::add(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_NORMALIZE_NS,
                    elapsed,
                );
                crate::compile_profile::inc(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_NORMALIZE_CALLS,
                );
            }
        }
        if let Some(payload) =
            self.try_lazy_simple_arrow_function_payload(is_async, params, &body_stmts, span, hint)
        {
            return Ok(payload);
        }
        self.next_compile_is_arrow = true;
        let t_proto = prof.then(std::time::Instant::now);
        let old_profile_member_arg_arrow_proto = self.profile_arrow_return_named_class_method_if_consequent_block_body_static_member_rhs_member_call_arg_arrow_proto;
        if profile_member_arg_arrow {
            self.profile_arrow_return_named_class_method_if_consequent_block_body_static_member_rhs_member_call_arg_arrow_proto = true;
        }
        let proto = self.compile_function_proto_with_name_hint(
            None,
            hint,
            FunctionSelfNameMode::Expression,
            is_async,
            false,
            params,
            &body_stmts,
        );
        self.profile_arrow_return_named_class_method_if_consequent_block_body_static_member_rhs_member_call_arg_arrow_proto =
            old_profile_member_arg_arrow_proto;
        let proto = proto?;
        if let Some(t0) = t_proto {
            let elapsed = t0.elapsed().as_nanos() as u64;
            if profile_babel_var_arrow {
                babel_var_arrow_proto_ns = elapsed;
            }
            crate::compile_profile::add(&crate::compile_profile::ARROW_PROTO_NS, elapsed);
            crate::compile_profile::inc(&crate::compile_profile::ARROW_PROTO_CALLS);
            if profile_member_arg_arrow {
                crate::compile_profile::add(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_PROTO_NS,
                    elapsed,
                );
                crate::compile_profile::inc(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_PROTO_CALLS,
                );
            }
        }
        let t_capture = prof.then(std::time::Instant::now);
        let captures = proto.upvalues.clone();
        if let Some(t0) = t_capture {
            let elapsed = t0.elapsed().as_nanos() as u64;
            if profile_babel_var_arrow {
                babel_var_arrow_capture_ns = elapsed;
            }
            crate::compile_profile::add(&crate::compile_profile::ARROW_CAPTURE_CLONE_NS, elapsed);
            crate::compile_profile::inc(&crate::compile_profile::ARROW_CAPTURE_CLONE_CALLS);
            if profile_member_arg_arrow {
                crate::compile_profile::add(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_CAPTURE_CLONE_NS,
                    elapsed,
                );
                crate::compile_profile::inc(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_CAPTURE_CLONE_CALLS,
                );
            }
        }
        let t_intern = prof.then(std::time::Instant::now);
        let idx = self
            .constants
            .intern(Constant::Function(std::rc::Rc::new(proto)));
        if let Some(t0) = t_intern {
            let elapsed = t0.elapsed().as_nanos() as u64;
            if profile_babel_var_arrow {
                babel_var_arrow_intern_ns = elapsed;
            }
            crate::compile_profile::add(&crate::compile_profile::ARROW_INTERN_NS, elapsed);
            crate::compile_profile::inc(&crate::compile_profile::ARROW_INTERN_CALLS);
            if profile_member_arg_arrow {
                crate::compile_profile::add(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_INTERN_NS,
                    elapsed,
                );
                crate::compile_profile::inc(
                    &crate::compile_profile::ARROW_RETURN_NAMED_CLASS_METHOD_IF_CONS_BLOCK_BODY_ASSIGN_STATIC_MEMBER_VALUE_CALL_MEMBER_ARG_ARROW_INTERN_CALLS,
                );
            }
        }
        if let (Some(name), Some(t0)) = (
            babel_var_arrow_name.as_deref(),
            t_babel_var_arrow_payload_total,
        ) {
            eprintln!(
                "cruft-profile-babel-parser-default-var-arrow-init-payload: source_url={} name={} hint={} total_ns={} normalize_ns={} proto_ns={} capture_ns={} intern_ns={} params={} body_stmts={} async={}",
                self.source_url,
                name,
                hint.unwrap_or("<none>"),
                t0.elapsed().as_nanos() as u64,
                babel_var_arrow_normalize_ns,
                babel_var_arrow_proto_ns,
                babel_var_arrow_capture_ns,
                babel_var_arrow_intern_ns,
                params.len(),
                body_stmts.len(),
                is_async,
            );
        }
        Ok((idx, captures))
    }

